style.css:
@-moz-document domain("youtube.com") {
body {
    background: url("https://i.imgur.com/FMuDziZ.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  #page-manager, #content, ytd-app, ytd-page-manager, ytd-browse, ytd-watch-flexy, tp-yt-app-drawer {
    background-color: rgba(255, 255, 255, 0.6) !important;
    backdrop-filter: blur(10px);
  }

  * {
    font-family: 'Brush Script MT', cursive !important;
    font-weight: bold !important;
    color: #222 !important;
  }

  a {
    color: #cc3399 !important;
  }

  a:hover {
    color: #ff66cc !important;
  }

  ytd-thumbnail, img {
    border-radius: 12px !important;
  }

  /* ? Hide default YouTube logo */
  #logo-icon {
    display: none !important;
  }

  /* ? Replace with blossom cursive "YouTube" */
  #logo::before {
    content: "";
    display: inline-block;
    width: 140px;
    height: 40px;
    background: url("https://i.imgur.com/qbhJRIz.png") no-repeat center center;
    background-size: contain;
  }
}
